import{z as E,x as d,o,c as m,q as n,j as l,D as s,d as t,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"自举","description":"","frontmatter":{"title":"自举","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bootstrapping.md","filePath":"cs/bootstrapping.md","lastUpdated":1791063341000}'),A={name:"cs/bootstrapping.md"};function B(h,a,g,c,f,u){const r=d("Mermaid");return o(),m("div",null,[a[2]||(a[2]=n('<h1 id="自举" tabindex="-1">自举 <a class="header-anchor" href="#自举" aria-label="Permalink to &quot;自举&quot;">​</a></h1><div class="epigraph"><p>用已有编译器编译新编译器的源，再用新编译器编译自己，直到二进制不动点。信任问题：第一份二进制从哪来。</p><footer>—— 据 Thompson, Reflections on Trusting Trust, 1984；Wirth 自举传统；对照 CompCert 抽取整理</footer></div><p>上一课<a href="/cs/compiler-fuzzing">Csmith</a> 测的是已得到的编译器。本课收束「程序语言与编译进阶」：缺口是<strong>自举链</strong>——Rust/GHC/Go 都用上一代编下一代。第一课 <a href="/cs/lex-flex">lex/flex</a> 从 word RAM 转入生成器；现在回到信任基。下一课程操作系统进阶从 <a href="/cs/fat-filesystem">FAT</a> 起，不在本课打开 VFS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>新语言没有编译器。阶段：用 C 写一个子集编译器，再扩展，直到能编自己。不动点：<code>cc_new(src) == cc_old(src)</code> 的二进制（或 ABI 允许的等价）。缺口是<strong>阶段与信任</strong>，不是差分测试。</p><p>Thompson：编译器可插入后门且自复制，源码审计不够。对策：多样编译器比较、从更小信任基重建（Guix 引导点名）。</p><h3 id="自举不是「递归函数」" tabindex="-1">自举不是「递归函数」 <a class="header-anchor" href="#自举不是「递归函数」" aria-label="Permalink to &quot;自举不是「递归函数」&quot;">​</a></h3><p>是工程过程，不是 \\(Y\\) 组合子。不要和<a href="/cs/recursion-theorem">递归定理</a> 混为一谈，尽管都有「自己谈自己」。</p><p><span class="marginnote">Thompson 1984 Turing 演讲。GHC stage。Rust bootstrap。CompCert 用 Coq 抽取，信任核不同。本课不写完整可引导发行版。</span></p><p><span class="marginnote">直觉类比：自举像「拉着自己的鞋带把自己提起来」——先有别人给的旧鞋带（stage0 二进制），编出一版新鞋带，再用新鞋带编自己，两版完全一样就说明站稳了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保留 stage0 二进制。stage1：stage0 编源。stage2：stage1 再编，应与 stage1 输出一致（或可解释的差异：路径嵌入）。交叉自举：用三元组在主机上为 target 产出。</p>',12)),(o(),l(p,null,{default:s(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22stage0%20%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20S1%5B%22%E7%BC%96%E8%AF%91%E6%BA%90%20%E2%86%92%20stage1%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%86%8D%E7%BC%96%E8%AF%91%20%E2%86%92%20stage2%22%5D%0A%20%20S2%20--%3E%20FIX%5B%22%E6%AF%94%E8%BE%83%20%2F%20%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 LTO/PGO：自举配置要钉死，否则二进制永远不等。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("时间戳、随机、"),e("code",null,"__DATE__"),t(" 破坏可复现。可复现构建是自举验证的朋友。不要在自举时混主机头文件——"),e("a",{href:"/cs/cross-compile-triple"},"交叉"),t("。")],-1)),a[6]||(a[6]=e("p",null,"多样复现：两份无关编译器编同一源，比 Thompson 后门。",-1)),a[7]||(a[7]=e("p",null,"stage1 与 stage2 输出若不一致，问题出在哪？三类典型原因各有对策：",-1)),(o(),l(p,null,{default:s(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22stage1%20%E2%89%A0%20stage2%22%5D%20--%3E%20T%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%20%2F%20__DATE__%20%E5%B5%8C%E5%85%A5%22%5D%0A%20%20D%20--%3E%20P%5B%22%E6%9E%84%E5%BB%BA%E8%B7%AF%E5%BE%84%E6%88%96%E9%9A%8F%E6%9C%BA%E9%A1%BA%E5%BA%8F%E4%B8%8D%E5%90%8C%22%5D%0A%20%20D%20--%3E%20O%5B%22%E4%BC%98%E5%8C%96%E4%B8%8E%20LTO%20%E9%85%8D%E7%BD%AE%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20T%20--%3E%20F%5B%22%E7%94%A8%20SOURCE_DATE_EPOCH%20%E7%AD%89%E9%92%89%E6%AD%BB%22%5D%0A%20%20P%20--%3E%20F%0A%20%20O%20--%3E%20F%0A%20%20F%20--%3E%20FIX%5B%22%E5%8F%AF%E5%A4%8D%E7%8E%B0%EF%BC%9A%E6%AF%94%E8%BE%83%E9%80%9A%E8%BF%87%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">为什么重要：比较不过就不敢说「到了不动点」，Thompson 式后门恰恰藏在「二进制和源码对不上」的缝隙里——可复现构建让每一步都能第三方重放验证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核引导。后课默认：语言实现靠自举链；信任可被 Thompson 攻击，需多样重建。程序语言与编译进阶到此结束；下一课 <a href="/cs/fat-filesystem">FAT</a>。</p><p>也不把自举当生物课。</p><p><span class="marginnote">常见误区：初学者容易以为「自举=递归调用自己」。递归是一次运行内的调用栈；自举是一个跨多轮构建的<strong>工程流程</strong>，每轮产物是独立的二进制，轮与轮之间靠文件与比较衔接。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自举：用编译器编译自己，直到二进制稳定。</li><li>Thompson：恶意编译器可存活在二进制里。</li><li>与 CompCert/Csmith：证明、测试、信任链三条腿。</li><li>出处：Thompson, 1984；对照 Leroy、Yang et al.；GNU/LLVM 自举实践。</li></ul>',7))])}const D=E(A,[["render",B]]);export{_ as __pageData,D as default};
